          intro: '<p>On the left is a small screen with a counter and a switch. Tap them and follow the highlight through the diagram: the event, the state it changes, the <code>body</code> SwiftUI re-runs, the new view tree, and the small difference that reaches the screen. Then turn on <strong>bug mode</strong>, where the same number is stored twice. Watch the two copies drift apart, and notice that a screen can only be as correct as its single source of truth.</p>',
