          intro: '<p>A NavigationStack is driven by an array of values called <code>path</code>. The root screen sits at the bottom and is never in <code>path</code>; each pushed value adds a screen on top. Push a few screens and watch <code>path</code> grow; go back and watch it shrink. Open the sheet with + and notice that <code>path</code> does not change. Then try <strong>Jump</strong>, which replaces the whole array at once, the way a deep link does. Turn on <strong>Predict first</strong> to call each result before it happens.</p>',
